func (obj *WrapInstruction) GetDiscriminator() []byte {
	return Instruction_Wrap[:]
}

// UnmarshalWithDecoder unmarshals the WrapInstruction from Borsh-encoded bytes prefixed with its discriminator.
func (obj *WrapInstruction) UnmarshalWithDecoder(decoder *binary.Decoder) error {
	var err error
	// Read the discriminator and check it against the expected value:
	discriminator, err := decoder.ReadDiscriminator()
	if err != nil {
		return fmt.Errorf("failed to read instruction discriminator for %s: %w", "WrapInstruction", err)
	}
	if discriminator != Instruction_Wrap {
		return fmt.Errorf("instruction discriminator mismatch for %s: expected %s, got %s", "WrapInstruction", Instruction_Wrap, discriminator)
	}
	// Deserialize `Amount`:
	err = decoder.Decode(&obj.Amount)
	if err != nil {
		return err
	}
	return nil
}

