	if indices[indexOffset] >= uint8(len(accountKeys)) {
		return fmt.Errorf("account index %d for %s is out of bounds (max: %d)", indices[indexOffset], "user_yt", len(accountKeys)-1)
	}
	obj.UserYt = accountKeys[indices[indexOffset]]
	indexOffset++
	// Set vault_underlying account from index
	if indices[indexOffset] >= uint8(len(accountKeys)) {
		return fmt.Errorf("account index %d for %s is out of bounds (max: %d)", indices[indexOffset], "vault_underlying", len(accountKeys)-1)
	}
	obj.VaultUnderlying = accountKeys[indices[indexOffset]]
