func (obj *WrapInstruction) GetAccountKeys() []solanago.PublicKey {
	keys := make([]solanago.PublicKey, 0)
	keys = append(keys, obj.User)
	keys = append(keys, obj.Market)
	keys = append(keys, obj.Registry)
	keys = append(keys, obj.Series)
	keys = append(keys, obj.UnderlyingMint)
	keys = append(keys, obj.PtMint)
	keys = append(keys, obj.YtMint)
	keys = append(keys, obj.UserUnderlying)
	keys = append(keys, obj.UserPt)
	keys = append(keys, obj.UserYt)
	keys = append(keys, obj.VaultUnderlying)
	keys = append(keys, obj.VaultAuthority)
	keys = append(keys, obj.TokenProgram)
	keys = append(keys, obj.PtTokenProgram)
	keys = append(keys, obj.YtTokenProgram)
	keys = append(keys, obj.AssociatedTokenProgram)
	keys = append(keys, obj.SystemProgram)
	return keys
}

